head.script:
scwin.onpageload = function() {

};

scwin.fn01 = async function(){
    for(i=0;i<30;i++){
        debugger;
        dataList1.insertJSON(i, [{}]);
    }

    for(i=0;i<30;i++){
        dataList1.setCellData(i, 'col1', i);
    }    

    gridView1.setFocusedCell(12, 0);

    if(await scwin.fn02() == -1){
        return -1;
    }
}

scwin.fn02 = async function(){
    var kkk = 12;
    var zzz = kkk+1;
    while(zzz <30){

        gridView1.setRowVisible(zzz, false);
        zzz = zzz+1;
    }
}

scwin.trigger1_onclick = function(e) {
    scwin.fn01();
};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('gridView1_body_tbody').getElementsByTagName('tr')[4].style.display == '';
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView1_body_tbody').getElementsByTagName('tr')[5].style.display == '';
	}	
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_4_tab_tabs2').click()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
